"""gui_main.py===========Hauptfenster mit allen Einstellungen im Dark-Mode-Fluent-Design.Thread-Sicherheit: Worker-Threads (Benchmark, Recorder) rufen NIEMALSdirekt Tkinter-Methoden auf. Sie nutzen ausschließlich self.after(0, ...),wodurch die Aktion in die Event-Loop des GUI-Threads eingereiht wird."""import osimport threadingfrom datetime import datetimefrom tkinter import filedialog, messageboximport customtkinter as ctkfrom audio_devices import get_audio_sourcesfrom benchmark import BenchmarkThreadfrom config import (    APP_NAME, APP_VERSION,    COLOR_ACCENT, COLOR_ACCENT_HOVER, COLOR_BG_CARD, COLOR_BG_HOVER,    COLOR_BG_INPUT, COLOR_BG_MAIN, COLOR_DANGER, COLOR_SUCCESS,    COLOR_TEXT_MUTED, COLOR_TEXT_PRIMARY, COLOR_WARNING,    DEFAULT_ENCODER, DEFAULT_FPS, DEFAULT_PRESET,    ENCODER_OPTIONS, FPS_OPTIONS,    MODE_FULLSCREEN, MODE_OPTIONS, MODE_REGION,    NO_AUDIO_LABEL, PRESET_OPTIONS,    RADIUS_LG, RADIUS_MD, RADIUS_SM,)from ffmpeg_utils import check_encoder_available, get_ffmpeg_pathfrom gui_mini import MiniPanelfrom platform_utils import (    get_default_videos_dir, get_platform_warning,    open_file_manager,)from recorder import RecorderThreadfrom region_selector import RegionSelectorctk.set_appearance_mode("dark")ctk.set_default_color_theme("blue")class MainWindow(ctk.CTk):    def __init__(self):        super().__init__()        self.title(f"{APP_NAME} v{APP_VERSION}")        self.geometry("560x760")        self.minsize(520, 700)        self.configure(fg_color=COLOR_BG_MAIN)        # ---- Zustand ----        self.region: tuple | None = None        self.audio_map: dict[str, str] = {}        self.recorder: RecorderThread | None = None        self.mini_panel: MiniPanel | None = None        self.benchmark_thread: BenchmarkThread | None = None        self._timer_job = None        self._blink_state = True        self._build_ui()        self._check_environment()        self._load_audio_devices_async()        self.protocol("WM_DELETE_WINDOW", self._on_close)    # ==================================================================    # UI-AUFBAU    # ==================================================================    def _build_ui(self):        # ---------------- Kopfbereich ----------------        header = ctk.CTkFrame(self, fg_color="transparent")        header.pack(fill="x", padx=24, pady=(22, 8))        ctk.CTkLabel(            header, text=APP_NAME,            font=("Segoe UI", 26, "bold"), text_color=COLOR_TEXT_PRIMARY,        ).pack(anchor="w")        ctk.CTkLabel(            header, text="Ressourcenschonende Bildschirmaufnahme",            font=("Segoe UI", 12), text_color=COLOR_TEXT_MUTED,        ).pack(anchor="w")        # ---------------- Benchmark-Karte ----------------        bench_card = self._make_card()        self.bench_btn = ctk.CTkButton(            bench_card, text="⚡  System testen & optimieren",            height=42, corner_radius=RADIUS_MD,            fg_color=COLOR_BG_INPUT, hover_color=COLOR_BG_HOVER,            font=("Segoe UI", 13, "bold"),            command=self._start_benchmark,        )        self.bench_btn.pack(fill="x", padx=14, pady=(14, 8))        self.bench_status = ctk.CTkLabel(            bench_card,            text="Noch nicht getestet – Standardeinstellungen aktiv.",            font=("Segoe UI", 11), text_color=COLOR_TEXT_MUTED,            wraplength=460, justify="left",        )        self.bench_status.pack(fill="x", padx=14, pady=(0, 14))        # ---------------- Aufnahme-Einstellungen ----------------        settings_card = self._make_card()        self._card_title(settings_card, "Aufnahme")        # Modus        self.mode_var = ctk.StringVar(value=MODE_FULLSCREEN)        row = self._labeled_row(settings_card, "Modus")        ctk.CTkOptionMenu(            row, values=MODE_OPTIONS, variable=self.mode_var,            width=250, height=34, corner_radius=RADIUS_SM,            fg_color=COLOR_BG_INPUT, button_color=COLOR_BG_INPUT,            button_hover_color=COLOR_BG_HOVER, font=("Segoe UI", 12),            command=self._on_mode_change,        ).pack(side="right", fill="x", expand=True)        self.region_label = ctk.CTkLabel(            settings_card, text="", font=("Segoe UI", 11),            text_color=COLOR_ACCENT, anchor="w",        )        self.region_label.pack(fill="x", padx=14)        # Framerate        self.fps_var = ctk.StringVar(value=DEFAULT_FPS)        row = self._labeled_row(settings_card, "Framerate")        ctk.CTkOptionMenu(            row, values=FPS_OPTIONS, variable=self.fps_var,            width=250, height=34, corner_radius=RADIUS_SM,            fg_color=COLOR_BG_INPUT, button_color=COLOR_BG_INPUT,            button_hover_color=COLOR_BG_HOVER, font=("Segoe UI", 12),        ).pack(side="right", fill="x", expand=True)        # Encoder        self.encoder_var = ctk.StringVar(value=DEFAULT_ENCODER)        row = self._labeled_row(settings_card, "Video-Encoder")        ctk.CTkOptionMenu(            row, values=ENCODER_OPTIONS, variable=self.encoder_var,            width=250, height=34, corner_radius=RADIUS_SM,            fg_color=COLOR_BG_INPUT, button_color=COLOR_BG_INPUT,            button_hover_color=COLOR_BG_HOVER, font=("Segoe UI", 12),            command=self._on_encoder_change,        ).pack(side="right", fill="x", expand=True)        self.encoder_warning = ctk.CTkLabel(            settings_card, text="", font=("Segoe UI", 11, "bold"),            text_color=COLOR_WARNING, anchor="w",        )        self.encoder_warning.pack(fill="x", padx=14)        # Preset        self.preset_var = ctk.StringVar(value=DEFAULT_PRESET)        row = self._labeled_row(settings_card, "Encoder-Preset")        ctk.CTkOptionMenu(            row, values=PRESET_OPTIONS, variable=self.preset_var,            width=250, height=34, corner_radius=RADIUS_SM,            fg_color=COLOR_BG_INPUT, button_color=COLOR_BG_INPUT,            button_hover_color=COLOR_BG_HOVER, font=("Segoe UI", 12),        ).pack(side="right", fill="x", expand=True)        # Audio        self.audio_var = ctk.StringVar(value=NO_AUDIO_LABEL)        row = self._labeled_row(settings_card, "Audio-Quelle")        self.audio_menu = ctk.CTkOptionMenu(            row, values=[NO_AUDIO_LABEL], variable=self.audio_var,            width=250, height=34, corner_radius=RADIUS_SM,            fg_color=COLOR_BG_INPUT, button_color=COLOR_BG_INPUT,            button_hover_color=COLOR_BG_HOVER, font=("Segoe UI", 12),        )        self.audio_menu.pack(side="right", fill="x", expand=True)        ctk.CTkLabel(settings_card, text="").pack(pady=2)  # Abstand        # ---------------- Speicherort ----------------        save_card = self._make_card()        self._card_title(save_card, "Speicherort")        row = ctk.CTkFrame(save_card, fg_color="transparent")        row.pack(fill="x", padx=14, pady=(0, 14))        self.path_var = ctk.StringVar(value=get_default_videos_dir())        ctk.CTkEntry(            row, textvariable=self.path_var, height=34,            corner_radius=RADIUS_SM, fg_color=COLOR_BG_INPUT,            border_width=0, font=("Segoe UI", 12),        ).pack(side="left", fill="x", expand=True)        ctk.CTkButton(            row, text="Durchsuchen", width=110, height=34,            corner_radius=RADIUS_SM,            fg_color=COLOR_BG_INPUT, hover_color=COLOR_BG_HOVER,            font=("Segoe UI", 12), command=self._browse_folder,        ).pack(side="left", padx=(8, 0))        # ---------------- Start-Button ----------------        self.start_btn = ctk.CTkButton(            self, text="●   Aufnahme starten",            height=54, corner_radius=RADIUS_LG,            fg_color=COLOR_ACCENT, hover_color=COLOR_ACCENT_HOVER,            font=("Segoe UI", 16, "bold"),            command=self._start_recording,        )        self.start_btn.pack(fill="x", padx=24, pady=(8, 6))        # ---------------- Statusleiste ----------------        self.status_label = ctk.CTkLabel(            self, text="Bereit.", font=("Segoe UI", 11),            text_color=COLOR_TEXT_MUTED, wraplength=500,        )        self.status_label.pack(fill="x", padx=24, pady=(0, 16))    # ---- UI-Hilfsfunktionen ----    def _make_card(self) -> ctk.CTkFrame:        card = ctk.CTkFrame(self, fg_color=COLOR_BG_CARD, corner_radius=RADIUS_LG)        card.pack(fill="x", padx=24, pady=8)        return card    def _card_title(self, parent, text: str):        ctk.CTkLabel(            parent, text=text, font=("Segoe UI", 13, "bold"),            text_color=COLOR_TEXT_PRIMARY, anchor="w",        ).pack(fill="x", padx=14, pady=(14, 8))    def _labeled_row(self, parent, label: str) -> ctk.CTkFrame:        """        Erzeugt eine Zeile mit Label links und gibt das Row-Frame zurück.        Das eigentliche Steuerelement (Dropdown etc.) muss ANSCHLIESSEND        MIT diesem zurückgegebenen 'row' als Parent erzeugt und        mit .pack(side='right', ...) eingefügt werden.        """        row = ctk.CTkFrame(parent, fg_color="transparent")        row.pack(fill="x", padx=14, pady=5)        ctk.CTkLabel(            row, text=label, font=("Segoe UI", 12),            text_color=COLOR_TEXT_MUTED, width=130, anchor="w",        ).pack(side="left")        return row    def _set_status(self, text: str, color: str = COLOR_TEXT_MUTED):        self.status_label.configure(text=text, text_color=color)    # ==================================================================    # UMGEBUNGSPRÜFUNG    # ==================================================================    def _check_environment(self):        """Prüft FFmpeg-Verfügbarkeit und Display-Server beim Start."""        try:            path = get_ffmpeg_path()            self._set_status(f"FFmpeg gefunden: {os.path.basename(path)}", COLOR_SUCCESS)        except FileNotFoundError as exc:            self._set_status(str(exc).split("\n")[0], COLOR_DANGER)            self.start_btn.configure(state="disabled")            self.bench_btn.configure(state="disabled")            messagebox.showerror("FFmpeg fehlt", str(exc))            return        warning = get_platform_warning()        if warning:            self._set_status(warning, COLOR_WARNING)    def _load_audio_devices_async(self):        """Geräteerkennung im Thread – blockiert den Start nicht."""        def worker():            try:                sources = get_audio_sources()            except Exception:                sources = []            self.after(0, lambda: self._apply_audio_devices(sources))        threading.Thread(target=worker, daemon=True).start()    def _apply_audio_devices(self, sources: list):        self.audio_map = {display: ident for display, ident in sources}        values = [NO_AUDIO_LABEL] + list(self.audio_map.keys())        self.audio_menu.configure(values=values)        self.audio_var.set(NO_AUDIO_LABEL)    # ==================================================================    # EVENT-HANDLER    # ==================================================================    def _on_mode_change(self, value: str):        if value == MODE_REGION:            self.withdraw()            self.after(220, self._open_region_selector)        else:            self.region = None            self.region_label.configure(text="")    def _open_region_selector(self):        try:            result = RegionSelector(self).select()        finally:            self.deiconify()            self.lift()        if result:            x, y, w, h = result            self.region = result            self.region_label.configure(text=f"✓ Bereich: {w} × {h} px  (bei {x}, {y})")        else:            self.region = None            self.mode_var.set(MODE_FULLSCREEN)            self.region_label.configure(text="")    def _on_encoder_change(self, value: str):        if value == "libx265":            self.encoder_warning.configure(text="⚠  Erfordert hohe CPU-Leistung!")            if not check_encoder_available("libx265"):                messagebox.showwarning(                    "Encoder nicht verfügbar",                    "libx265 ist in dieser FFmpeg-Version nicht enthalten.\n"                    "Bitte installiere eine Full-Build oder nutze libx264.",                )                self.encoder_var.set("libx264")                self.encoder_warning.configure(text="")        else:            self.encoder_warning.configure(text="")    def _browse_folder(self):        folder = filedialog.askdirectory(            title="Speicherort wählen", initialdir=self.path_var.get()        )        if folder:            self.path_var.set(folder)    # ==================================================================    # BENCHMARK    # ==================================================================    def _start_benchmark(self):        self.bench_btn.configure(state="disabled", text="⏳  Test läuft ...")        self.start_btn.configure(state="disabled")        self.bench_status.configure(            text="Testaufnahme läuft ...", text_color=COLOR_TEXT_MUTED        )        self.benchmark_thread = BenchmarkThread(            on_progress=lambda t: self.after(0, self._bench_progress, t),            on_finish=lambda r: self.after(0, self._bench_finish, r),            on_error=lambda m: self.after(0, self._bench_error, m),        )        self.benchmark_thread.start()    def _bench_progress(self, text: str):        self.bench_status.configure(text=text, text_color=COLOR_TEXT_MUTED)    def _bench_finish(self, result: dict):        # Entscheidungs-Matrix anwenden        self.fps_var.set(result["fps"])        self.encoder_var.set(result["encoder"])        self.preset_var.set(result["preset"])        self._on_encoder_change(result["encoder"])        self.bench_status.configure(            text=(f"{result['message']}\n"                  f"Ø CPU: {result['avg_cpu']} %  •  Spitze: {result['peak_cpu']} %  •  "                  f"Preset: {result['preset']}"),            text_color=result["color"],        )        self._reset_bench_buttons()        messagebox.showinfo(result["title"], result["message"])    def _bench_error(self, message: str):        self.bench_status.configure(text=message, text_color=COLOR_DANGER)        self._reset_bench_buttons()        messagebox.showerror("Benchmark fehlgeschlagen", message)    def _reset_bench_buttons(self):        self.bench_btn.configure(state="normal", text="⚡  System testen & optimieren")        self.start_btn.configure(state="normal")    # ==================================================================    # AUFNAHME    # ==================================================================    def _start_recording(self):        folder = self.path_var.get().strip()        if not os.path.isdir(folder):            messagebox.showerror("Ungültiger Pfad", "Der Speicherort existiert nicht.")            return        mode_region = self.mode_var.get() == MODE_REGION        if mode_region and not self.region:            messagebox.showwarning("Kein Bereich", "Bitte zuerst einen Bereich wählen.")            return        timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")        output_path = os.path.join(folder, f"Aufnahme_{timestamp}.mp4")        audio_label = self.audio_var.get()        audio_device = self.audio_map.get(audio_label) if audio_label != NO_AUDIO_LABEL else None        settings = {            "output_path": output_path,            "fps": self.fps_var.get(),            "encoder": self.encoder_var.get(),            "preset": self.preset_var.get(),            "mode_region": mode_region,            "region": self.region,            "audio_device": audio_device,        }        self.recorder = RecorderThread(            settings,            on_started=lambda: self.after(0, self._on_recording_started),            on_stopped=lambda p, s: self.after(0, self._on_recording_stopped, p, s),            on_error=lambda m: self.after(0, self._on_recording_error, m),        )        self.recorder.start()        self._set_status("Aufnahme wird gestartet ...", COLOR_ACCENT)    def _on_recording_started(self):        # Hauptfenster ausblenden -> spart RAM/CPU auf schwacher Hardware        self.withdraw()        self.mini_panel = MiniPanel(            self, fps=self.fps_var.get(),            on_pause=self._toggle_pause, on_stop=self._stop_recording,        )        self.mini_panel.set_fps_text(f"{self.fps_var.get()} FPS")        self._tick_timer()    def _tick_timer(self):        """Aktualisiert Timer + Blinkpunkt im Sekundentakt."""        if not (self.recorder and self.mini_panel):            return        try:            self.mini_panel.update_timer(self.recorder.get_elapsed())            if not self.recorder.is_paused:                self._blink_state = not self._blink_state                self.mini_panel.blink_dot(self._blink_state)        except Exception:            return        self._timer_job = self.after(500, self._tick_timer)    def _toggle_pause(self) -> bool:        return self.recorder.toggle_pause() if self.recorder else False    def _stop_recording(self):        if self._timer_job:            self.after_cancel(self._timer_job)            self._timer_job = None        if self.recorder:            self.recorder.stop()    def _on_recording_stopped(self, path: str, success: bool):        if self.mini_panel:            try:                self.mini_panel.destroy()            except Exception:                pass            self.mini_panel = None        self.deiconify()        self.lift()        self.recorder = None        if success:            size_mb = os.path.getsize(path) / (1024 * 1024)            self._set_status(                f"✓ Gespeichert: {os.path.basename(path)}  ({size_mb:.1f} MB)",                COLOR_SUCCESS,            )            if messagebox.askyesno(                "Aufnahme fertig",                f"Video gespeichert:\n{os.path.basename(path)}  ({size_mb:.1f} MB)\n\n"                "Ordner jetzt öffnen?",            ):                open_file_manager(path)        else:            self._set_status("Aufnahme fehlgeschlagen – keine Datei erzeugt.", COLOR_DANGER)    def _on_recording_error(self, message: str):        short = message.split("\n")[0][:200]        self._set_status(short, COLOR_DANGER)        messagebox.showerror("Aufnahmefehler", message[:600])    # ==================================================================    def _on_close(self):        if self.recorder and self.recorder.is_active:            if not messagebox.askyesno(                "Aufnahme läuft",                "Es läuft noch eine Aufnahme. Wirklich beenden?"            ):                return            self.recorder.stop()            self.recorder.join(timeout=8)        if self.benchmark_thread and self.benchmark_thread.is_alive():            self.benchmark_thread.cancel()        self.destroy()